// Give every answer one deterministic label by comparing it with the frozen test question.
// Rules are checked in a fixed order; the first rule that fits decides the label.
const settings = $('Settings').first().json;
const questions = $('Extract questions').all();
const results = $('Extract results').all();

// Article ids that exist in the knowledge-base version of this run.
let index = $('Extract index').first().json.data;
if (Array.isArray(index)) {
  index = index[0];
}
const existingIds = [];
for (const article of index.articles) {
  existingIds.push(article.id);
}

// Look up each result row by its question id.
const resultById = {};
for (const item of results) {
  resultById[item.json.question_id] = item.json;
}

// "I don't know", "I don't know." and "i do not know" all count as giving up.
function saysDontKnow(answer) {
  const text = answer.toLowerCase().replace(/[’`]/g, "'").trim();
  return text.startsWith("i don't know") || text.startsWith('i do not know');
}

// expected_keywords: groups separated by ';' must all appear; '|' means any one of the group.
function hasKeywords(answer, expected) {
  const text = answer.toLowerCase();
  for (const group of expected.split(';')) {
    let groupFound = false;
    for (const option of group.split('|')) {
      if (option.trim() !== '' && text.includes(option.trim().toLowerCase())) {
        groupFound = true;
      }
    }
    if (!groupFound) {
      return false;
    }
  }
  return true;
}

const rows = [];
let position = 0;
for (const item of questions) {
  const q = item.json;
  const r = resultById[q.question_id];
  position = position + 1;

  const expected = q.expected_action;
  const answer = r.bot_answer || '';
  const gaveUp = saysDontKnow(answer);
  const top3 = [r.top1_id, r.top2_id, r.top3_id];
  const articleExists = existingIds.includes(q.expected_article);
  const articleRetrieved = top3.includes(q.expected_article);

  let label = '';
  let reason = '';
  if (expected === 'escalate' && r.route === 'escalate') {
    label = 'correct';
    reason = 'escalated on keyword "' + r.matched_keyword + '"';
  } else if (expected === 'escalate' || r.route === 'escalate') {
    label = 'bad_escalation';
    if (expected === 'escalate') {
      reason = 'should escalate, but no keyword matched';
    } else {
      reason = 'escalated on keyword "' + r.matched_keyword + '" but should be answered';
    }
  } else if (expected === 'dont_know') {
    if (gaveUp) {
      label = 'correct';
      reason = "said I don't know (route " + r.route + ')';
    } else {
      label = 'made_up';
      reason = 'answered a question that no article covers';
    }
  } else if (!articleExists) {
    if (gaveUp) {
      label = 'missing_content';
      reason = 'article ' + q.expected_article + ' does not exist in kb ' + r.kb_version;
    } else {
      label = 'made_up';
      reason = 'answered although article ' + q.expected_article + ' does not exist';
    }
  } else if (!gaveUp && hasKeywords(answer, q.expected_keywords)) {
    label = 'correct';
    reason = 'answer contains: ' + q.expected_keywords;
  } else if (gaveUp && articleRetrieved) {
    label = 'dead_end';
    reason = "said I don't know although " + q.expected_article + ' was in the top 3 (route ' + r.route + ')';
  } else if (!articleRetrieved) {
    label = 'retrieval_miss';
    reason = q.expected_article + ' not in top 3 (' + top3.join(', ') + ')';
  } else {
    label = 'wrong_answer';
    reason = q.expected_article + ' retrieved, but answer lacks: ' + q.expected_keywords;
  }

  // Every 4th question is picked in advance for the manual spot check.
  let spotCheck = 'no';
  if (position % 4 === 0) {
    spotCheck = 'yes';
  }

  rows.push({
    json: {
      run_id: settings.run_id,
      question_id: q.question_id,
      category: q.category,
      question: q.question,
      expected_action: expected,
      expected_article: q.expected_article,
      expected_keywords: q.expected_keywords,
      route: r.route,
      top1_id: r.top1_id,
      top1_score: r.top1_score,
      cited_ids: r.cited_ids,
      bot_answer: answer,
      label: label,
      reason: reason,
      spot_check: spotCheck,
      manual_label: '',
    },
  });
}
return rows;
